import{_ as r}from"./chunks/uavcan_wiring.0Ml-olhd.js";import{_ as o,o as t,c as n,al as i,j as e,a as l}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"CAN (DroneCAN & Cyphal)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/can/index.md","filePath":"zh/can/index.md"}'),s={name:"zh/can/index.md"};function h(p,a,c,d,u,C){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="can-dronecan-cyphal" tabindex="-1">CAN (DroneCAN &amp; Cyphal) <a class="header-anchor" href="#can-dronecan-cyphal" aria-label="Permalink to &quot;CAN (DroneCAN &amp; Cyphal)&quot;">​</a></h1><p><a href="https://en.wikipedia.org/wiki/CAN_bus" target="_blank" rel="noreferrer">Controller Area Network (CAN)</a> is a robust wired network that allows drone components such as flight controller, ESCs, sensors, and other peripherals, to communicate with each other.</p><p>It is particularly recommended on larger vehicles.</p><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><p>CAN it is designed to be democratic and uses differential signaling. For this reason it is very robust even over longer cable lengths (on large vehicles), and avoids a single point of failure. CAN 还允许来自外设的状态反馈，并通过总线方便的进行固件升级。</p><p>PX4 has the ability to track and log detailed information from CAN devices, including firmware versions, hardware versions, and serial numbers. This enables unique identification and lifecycle tracking of hardware connected to the flight controller. See <a href="./../debug/asset_tracking">Asset Tracking</a> for more information.</p><p>PX4 支持与 CAN 设备通信的两个软件协议：</p><ul><li><a href="./../dronecan/">DroneCAN</a>: PX4 推荐大多数常见的设置。 它得到了 PX4 的很好支持，是一个成熟的产品，具有广泛的外围支持，并经过多年的测试。</li><li><a href="https://opencyphal.org" target="_blank" rel="noreferrer">Cyphal</a>：PX4 支持是一个“在进行中的工作”。 Cyphal 是一种更新的协议，允许更多的灵活性和配置，尤其是对于较大和较复杂的载具。 它还没有被广泛应用。</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>DroneCAN 和 Cyphal 都是早先一个叫做UAVCAN的项目。 在2022年，该项目分为两个部分：原始版本的 UAVCAN (UAVCAN v0) 更名为 DroneCAN，较新的 UAVCAN v1 更名为 Cyphal。 这两项协议之间的差异在<a href="https://forum.opencyphal.org/t/cyphal-vs-dronecan/1814" target="_blank" rel="noreferrer">Cyphal vs. DroneCAN</a>中作了概述。</p></div><p>PX4不支持KDECAN等无人驾驶飞机的其他CAN软件协议(撰写时)。</p><h2 id="布线" tabindex="-1">布线 <a class="header-anchor" href="#布线" aria-label="Permalink to &quot;布线&quot;">​</a></h2><p>CAN 网络的接线对于 DroneCAN 和 Cyphal/CAN 是一样 (实际上对所有的 CAN 网络都一样)。</p><p>Devices within a network are connected in a <em>daisy-chain</em> in any order (this differs from UARTs peripherals, where you attach just one component per port).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don&#39;t connect each CAN peripheral to a separate CAN port! Unlike UARTs, CAN peripherals are designed to be daisy chained, with additional ports such as <code>CAN2</code> used for <a href="#redundancy">redundancy</a>.</p></div><p>在链的任一端，应该在两个数据线之间连接一个 120Ω 的终端电阻。 飞控和一些 GNSS 模块为了方便使用内置了终端电阻， 因此应该放在链的终端。 否则，你可以使用终端电阻，比如 <a href="https://shop.zubax.com/products/uavcan-micro-termination-plug?variant=6007985111069" target="_blank" rel="noreferrer">Zubax Robotics 的这款</a>。如果你有JST - GH压接工具，也可以自己焊接一个。</p><p>下图显示了一个 CAN 总线连接飞控到 4 个 CAN 电调和一个 GNSS 的示例。 It includes a redundant bus connected to <code>CAN 2</code>.</p><p><img src="'+r+'" alt="CAN 布线"></p><p>图中未显示任何电源接线。 参考制造商的说明，确认组件是否需要单独供电，还是可以通过 CAN 总线供电。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For more information, see <a href="https://wiki.zubax.com/public/cyphal/CyphalCAN-device-interconnection?pageId=2195476" target="_blank" rel="noreferrer">Cyphal/CAN device interconnection</a> (kb.zubax.com). 虽然本文是以 Cyphal 协议为基础编写的，但同样适用于 DroneCAN 硬件和任何其他 CAN 设置。 如需了解更复杂的场景，请参考 <a href="https://forum.opencyphal.org/t/on-can-bus-topology-and-termination/1685" target="_blank" rel="noreferrer">论CAN总线拓扑结构与终端匹配</a>。</p></div><h3 id="连接器" tabindex="-1">连接器 <a class="header-anchor" href="#连接器" aria-label="Permalink to &quot;连接器&quot;">​</a></h3><p>Pixhawk标准兼容的 CAN 设备使用 4 引脚的 JST-GH 连接器为 CAN。 在连线接线时，有两个连接器用于输入和输出（飞行控制器除外和一些内置终止的全球导航卫星系统（GNSS）设备除外）； 它仅有一个JST-GH连接器)。</p><p>其他(非Pixhawk兼容的)设备可能使用不同的连接器。 然而，只要设备固件支持DroneCAN 或Cyphal，它就可以使用。</p><h3 id="冗余" tabindex="-1">冗余 <a class="header-anchor" href="#冗余" aria-label="Permalink to &quot;冗余&quot;">​</a></h3><p>DroneCAN 和 Cyphal/CAN支持使用第二个(冗余) CAN 接口。 这是完全可选的，但会增加连接的强度。</p><p>Pixhawk flight controllers come with 2 CAN interfaces; if your peripherals support 2 CAN interfaces as well, it is recommended to wire both up for increased safety.</p><h3 id="flight-controllers-with-multiple-can-ports" tabindex="-1">Flight Controllers with Multiple CAN Ports <a class="header-anchor" href="#flight-controllers-with-multiple-can-ports" aria-label="Permalink to &quot;Flight Controllers with Multiple CAN Ports&quot;">​</a></h3><p><a href="./../flight_controller/">Flight Controllers</a> may have up to three independent CAN ports, such as <code>CAN1</code>, <code>CAN2</code>, <code>CAN3</code> (neither DroneCAN or Cyphal support more than three). Note that you can&#39;t have both DroneCAN and Cyphal running on PX4 at the same time.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You only <em>need</em> one CAN port to support an arbitrary number of CAN devices using a particular CAN protocol. Don&#39;t connect each CAN peripheral to a separate CAN port!</p></div><p>Generally you&#39;ll daisy all CAN peripherals off a single port, and if there is more than one CAN port, use the second one for <a href="#redundancy">redundancy</a>. If there are three ports, you might use the remaining network for devices that support another CAN protocol.</p><p>The documentation for your flight controller should indicate which ports are supported/enabled. At runtime you can check what DroneCAN ports are enabled and their status using the following command on the <a href="./../debug/mavlink_shell">MAVLink Shell</a> (or some other console):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uavcan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Note that you can also check the number of supported CAN interfaces for a board by searching for <code>CONFIG_BOARD_UAVCAN_INTERFACES</code> in its <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6xrt/default.px4board#" target="_blank" rel="noreferrer">default.px4board</a> configuration file.</p><h2 id="固件" tabindex="-1">固件 <a class="header-anchor" href="#固件" aria-label="Permalink to &quot;固件&quot;">​</a></h2><p>CAN 外围设备可以运行专有或开源固件(请检查制造商指南以确认所需的设置)。</p><p>PX4 可以构建在支持的 CAN 硬件上作为开源的 DroneCAN 固件运行。 更多信息请参考 <a href="./../dronecan/px4_cannode_fw">PX4 DroneCAN 固件</a>。</p><h2 id="支持和配置" tabindex="-1">支持和配置 <a class="header-anchor" href="#支持和配置" aria-label="Permalink to &quot;支持和配置&quot;">​</a></h2><p><a href="./../dronecan/">DroneCAN 设置和配置</a></p><p><a href="./../dronecan/px4_cannode_fw">PX4 DroneCAN 固件</a></p><h2 id="视频" tabindex="-1">视频 <a class="header-anchor" href="#视频" aria-label="Permalink to &quot;视频&quot;">​</a></h2><h3 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to &quot;DroneCAN&quot;">​</a></h3><p>关于 DroneCAN (UAVCANv0) 的介绍和在 QGroundControl 中设置的实用示例：</p>',41),e("lite-youtube",{videoid:"IZMTq9fTiOM",title:"Intro to DroneCAN (UAVCANv0) and practical example with setup in QGroundControl"},null,-1),e("h3",{id:"cyphal",tabindex:"-1"},[l("Cyphal "),e("a",{class:"header-anchor",href:"#cyphal","aria-label":'Permalink to "Cyphal"'},"​")],-1),e("p",null,"无人机的 UAVCAN v1 (Cyphal) - PX4 开发者峰会虚拟2020",-1),e("lite-youtube",{videoid:"6Bvtn_g8liU",title:"UAVCAN v1 for drones — PX4 Developer Summit Virtual 2020"},null,-1),e("hr",null,null,-1),e("p",null,"在NXP UAVCAN板上使用UAVCAN v1和PX4入门——2020年PX4开发者峰会线上会议",-1),e("lite-youtube",{videoid:"MwdHwjaXYKs",title:"Getting started using UAVCAN v1 with PX4 on the NXP UAVCAN Board"},null,-1),e("hr",null,null,-1),e("p",null,"UAVCAN：一个高度可靠的发布-订阅协议，用于硬实时车辆内网络 — PX4 开发者虚拟峰会 2019",-1),e("lite-youtube",{videoid:"MBtROivYPik",title:"UAVCAN: a highly dependable publish-subscribe protocol for hard ..."},null,-1)])])}const m=o(s,[["render",h]]);export{f as __pageData,m as default};
